type WaInstance struct {
	ID                   pgtype.UUID      `json:"id"`
	TenantID             pgtype.UUID      `json:"tenantId"`
	Label                string           `json:"label"`
	PhoneNumber          pgtype.Text      `json:"phoneNumber"`
	Status               string           `json:"status"`
	LastConnectedAt      pgtype.Timestamp `json:"lastConnectedAt"`
	LastDisconnectReason pgtype.Text      `json:"lastDisconnectReason"`
	AiEnabled            bool             `json:"aiEnabled"`
	AiProvider           pgtype.Text      `json:"aiProvider"`
	AiModel              pgtype.Text      `json:"aiModel"`
	AiSystemPrompt       pgtype.Text      `json:"aiSystemPrompt"`
	AiTemperature        pgtype.Text      `json:"aiTemperature"`
	AiMaxHistory         int32            `json:"aiMaxHistory"`
	CreatedAt            pgtype.Timestamp `json:"createdAt"`
	UpdatedAt            pgtype.Timestamp `json:"updatedAt"`
	AiProviderConfigID   pgtype.UUID      `json:"aiProviderConfigId"`
	// WhatsApp number (E.164, no leading +) the AI sends handoff alerts to. Must differ from the instance's own paired phone_number — whatsmeow rejects self-sends.
	AdminPhone pgtype.Text `json:"adminPhone"`
	// After this many hours of admin inactivity, AI auto-resumes when the customer sends a new message. 0 = never auto-resume (manual only). Range 0-168.
	HandoffAutoResumeHours int32       `json:"handoffAutoResumeHours"`
	OtpLoginEnabled        bool        `json:"otpLoginEnabled"`
	BranchID               pgtype.UUID `json:"branchId"`
}

